     1|/**
     2| * IVX-SENIOR-DEV-01 — AI Reasoning Client
     3| *
     4| * Thin client over the Vercel AI Gateway (https://ai-gateway.vercel.sh/v1)
     5| * used by the autonomous senior developer worker to reason about code changes.
     6| * Mirrors the proven call pattern in backend/services/ivx-ai-provider-fallback.ts.
     7| *
     8| * Reads credentials from process.env:
     9| *   - OPENAI_API_KEY or IVX_AI_GATEWAY_KEY (vck_ key, required)
    10| */
    11|
    12|const GATEWAY_URL = 'https://ai-gateway.vercel.sh/v1/chat/completions';
    13|
    14|export interface AIReasoningResult {
    15|  ok: boolean;
    16|  content: string;
    17|  error: string | null;
    18|  model: string;
    19|  usage: { promptTokens: number | null; completionTokens: number | null } | null;
    20|}
    21|
    22|function readEnv(name: string): string {
    23|  return (process.env[name] ?? '').trim();
    24|}
    25|
    26|function resolveApiKey(): string {
    27|  return readEnv('OPENAI_API_KEY') || readEnv('IVX_AI_GATEWAY_KEY');
    28|}
    29|
    30|function resolveModel(): string {
    31|  // Vercel AI Gateway requires the provider prefix (e.g. "openai/gpt-4o").
    32|  // The runtime health endpoint confirms the working key is vck_ + openai/gpt-4o.
    33|  // Default to the proven-working model so AI planning actually succeeds.
    34|  const explicit = readEnv('IVX_SENIOR_DEV_MODEL');
    35|  if (explicit) return explicit;
    36|  const fallback = readEnv('IVX_OPENAI_FALLBACK_MODEL');
    37|  if (fallback) return fallback.startsWith('openai/') || fallback.startsWith('anthropic/') ? fallback : `openai/${fallback}`;
    38|  return 'openai/gpt-4o';
    39|}
