    41|/**
    42| * Ask the AI gateway a question and return the assistant message content.
    43| * Returns { ok: false, error } on any failure — the worker must handle gracefully.
    44| */
    45|export async function askAI(prompt: string, opts: { systemPrompt?: string; maxTokens?: number; timeoutMs?: number } = {}): Promise<AIReasoningResult> {
    46|  const apiKey = resolveApiKey();
    47|  if (!apiKey) {
    48|    return { ok: false, content: '', error: 'AI gateway key not configured (OPENAI_API_KEY or IVX_AI_GATEWAY_KEY).', model: 'none', usage: null };
    49|  }
    50|  const model = resolveModel();
    51|  const messages: { role: string; content: string }[] = [];
    52|  if (opts.systemPrompt) messages.push({ role: 'system', content: opts.systemPrompt });
    53|  messages.push({ role: 'user', content: prompt });
    54|
    55|  const controller = new AbortController();
    56|  const timeout = setTimeout(() => controller.abort(), opts.timeoutMs ?? 60_000);
    57|  try {
    58|    const res = await fetch(GATEWAY_URL, {
    59|      method: 'POST',
    60|      headers: {
    61|        Authorization: `Bearer ${apiKey}`,
    62|        'Content-Type': 'application/json',
    63|      },
    64|      body: JSON.stringify({
    65|        model,
    66|        messages,
    67|        max_tokens: opts.maxTokens ?? 2000,
    68|        temperature: 0.2,
    69|      }),
    70|      signal: controller.signal,
    71|    });
    72|    if (!res.ok) {
    73|      const text = await res.text().catch(() => '');
    74|      return { ok: false, content: '', error: `AI gateway HTTP ${res.status}: ${text.slice(0, 300)}`, model, usage: null };
    75|    }
    76|    const data = (await res.json()) as Record<string, unknown>;
    77|    const choices = Array.isArray(data.choices) ? (data.choices as Array<Record<string, unknown>>) : [];
    78|    const message = choices[0]?.message as Record<string, unknown> | undefined;
    79|    const content = typeof message?.content === 'string' ? message.content : '';
    80|    const usage = data.usage as Record<string, unknown> | undefined;
    81|    return {
    82|      ok: true,
    83|      content,
    84|      error: null,
    85|      model,
    86|      usage: {
    87|        promptTokens: typeof usage?.prompt_tokens === 'number' ? usage.prompt_tokens : null,
    88|        completionTokens: typeof usage?.completion_tokens === 'number' ? usage.completion_tokens : null,
    89|      },
    90|    };
    91|  } catch (err) {
    92|    return { ok: false, content: '', error: err instanceof Error ? err.message : String(err), model, usage: null };
    93|  } finally {
    94|    clearTimeout(timeout);
    95|  }
