   100| * If repoFileTree is provided, it is injected so the AI plans against actual
   101| * files (not hallucinated paths).
   102| */
   103|export async function planEngineeringTask(taskPrompt: string, repoFileTree: string[] = []): Promise<AIReasoningResult> {
   104|  const fileTreeSection = repoFileTree.length > 0
   105|    ? `\n\n--- REPOSITORY FILE TREE (actual files you may inspect or edit) ---\n${repoFileTree.join('\n')}\n--- END FILE TREE ---\n\nIMPORTANT: Only reference files that appear in the file tree above. Do NOT invent paths.\n`
   106|    : '';
   107|  const systemPrompt = [
   108|    'You are an autonomous senior developer reasoning about a code change request.',
   109|    'Inspect the repository context given and return a JSON object with keys:',
   110|    '  "summary": one-line description of the change,',
   111|    '  "filesToInspect": array of repo-relative file paths to read before editing (must exist in the file tree if provided),',
   112|    '  "filesToChange": array of {path, reason} describing each file to edit (must exist in the file tree if provided),',
   113|    '  "testsToRun": array of test commands (e.g. "bun test backend/services/foo.test.ts"),',
   114|    '  "requiresDeploy": boolean — true if the change must deploy to production,',
   115|    '  "rollbackNotes": short rollback plan if the change breaks production.',
   116|    'Return ONLY the JSON object. No prose, no markdown fences.',
   117|    'Prefer the SMALLEST safe change that fixes a real defect. Do NOT invent file paths.',
   118|  ].join('\n');
