   122|/**
   123| * Ask the AI to generate a file patch given the current file content + goal.
   124| * Returns the full new file content (not a diff) for simplicity and reliability.
   125| *
   126| * CRITICAL: the prompt enforces SURGICAL minimal edits. The AI must change ONLY
   127| * the lines required by the goal and preserve every other line verbatim. This is
   128| * the root-cause fix for the prior failures where the AI rewrote whole large
   129| * files (breaking tsc/tests on 4 consecutive tasks). Re-writing a 600-line file
   130| * to fix a one-line defect guarantees type/test drift.
   131| */
   132|export async function generateFilePatch(input: { filePath: string; currentContent: string; goal: string; priorContext?: string }): Promise<AIReasoningResult> {
   133|  const systemPrompt = [
