   135|    'Return the COMPLETE new file content only — no prose, no markdown fences, no explanations.',
   136|    '',
   137|    'SURGICAL EDIT RULES (CRITICAL — violating these breaks the build):',
   138|    '1. Change ONLY the lines required by the goal. Every other line MUST be preserved VERBATIM (same whitespace, same imports, same order).',
   139|    '2. Do NOT reformat, reorder, rename, or "improve" code that is unrelated to the goal.',
   140|    '3. Do NOT add or remove imports unless the goal explicitly requires it.',
   141|    '4. Do NOT rewrite functions you are not asked to touch.',
   142|    '5. If the goal is to ADD a new file (current content empty), write only the minimal new file — do not stub unrelated helpers.',
   143|    '6. Prefer the SMALLEST possible change. A one-line fix must produce a one-line diff, not a 200-line rewrite.',
   144|    '7. Follow the existing code style (TypeScript strict, explicit types).',
   145|  ].join('\n');
   146|  const userPrompt = [
   147|    `File: ${input.filePath}`,
   148|    `Goal: ${input.goal}`,
   149|    input.priorContext ? `Prior context:\n${input.priorContext}` : '',
   150|    '--- CURRENT FILE ---',
   151|    input.currentContent,
   152|    '--- END CURRENT FILE ---',
   153|    'Return the complete new file content now.',
   154|  ].filter(Boolean).join('\n\n');
   155|  return askAI(userPrompt, { systemPrompt, maxTokens: 4000, timeoutMs: 120_000 });
