     1|/**
     2| * IVX AI Multi-Provider Fallback Chain
     3| *
     4| * Adds a safe, opt-in fallback abstraction around `requestIVXAIText`. The
     5| * primary provider stays the existing Vercel AI Gateway path
     6| * (`IVX_AI_GATEWAY_KEY`). Fallbacks are ONLY registered when their
     7| * provider-specific env var is set; otherwise the chain is a no-op and the
     8| * caller still sees the original primary failure.
     9| *
    10| * Hard rules:
    11| *   - never log API keys, never log prompt content, never echo bodies
    12| *   - never return secret values from the status endpoint (name + status only)
    13| *   - never invoke a fallback unless its env key exists
    14| *   - never use a fallback for streaming (yet) — only for completion replies
    15| *   - classified failures (auth/quota/timeout/network/unknown) so callers can
    16| *     decide policy; only retryable classes trigger fallback
    17| */
    18|
    19|export type IVXProviderName = 'ivx_ai_gateway' | 'openai_direct' | 'anthropic_direct';
    20|
    21|/** External toolkit fallback was permanently removed on 2026-07-16 by owner directive.
    22| * The IVX provider chain is exclusively owner-controlled: OpenAI direct + Anthropic direct.
    23| * No external proxy, no external credits, no external AI Cloud dependency. */
    24|export type IVXProviderFailureClass =
    25|  | 'auth'
    26|  | 'quota'
    27|  | 'rate_limit'
    28|  | 'timeout'
    29|  | 'network'
    30|  | 'bad_request'
    31|  | 'server_error'
    32|  | 'unknown';
    33|
    34|export type IVXProviderStatus = {
    35|  name: IVXProviderName;
    36|  role: 'primary' | 'fallback';
    37|  configured: boolean;
    38|  /** Which env var(s) gate this provider. Never returns the actual value. */
    39|  envGates: string[];
    40|};
