    57|/** Public, secret-free provider snapshot for the owner status route. */
    58|export function getIVXProviderChainSnapshot(): {
    59|  primary: IVXProviderStatus;
    60|  fallbacks: IVXProviderStatus[];
    61|  fallbackEnabled: boolean;
    62|} {
    63|  const primary: IVXProviderStatus = {
    64|    name: 'ivx_ai_gateway',
    65|    role: 'primary',
    66|    configured: hasEnv('IVX_AI_GATEWAY_KEY'),
    67|    envGates: ['IVX_AI_GATEWAY_KEY'],
    68|  };
    69|  const fallbacks: IVXProviderStatus[] = [
    70|    {
    71|      name: 'openai_direct',
    72|      role: 'fallback',
    73|      configured: hasEnv('OPENAI_API_KEY'),
    74|      envGates: ['OPENAI_API_KEY'],
    75|    },
    76|    {
    77|      name: 'anthropic_direct',
    78|      role: 'fallback',
    79|      configured: hasEnv('ANTHROPIC_API_KEY'),
    80|      envGates: ['ANTHROPIC_API_KEY'],
    81|    },
    82|    // External toolkit cutover (2026-07-07): the external_toolkit fallback has been
    83|    // removed. The IVX provider chain is now exclusively IVX-owned:
    84|    // Vercel AI Gateway (primary) + OpenAI direct + Anthropic direct.
    85|  ];
    86|  const fallbackEnabled = fallbacks.some((p) => p.configured);
    87|  return { primary, fallbacks, fallbackEnabled };
