    90|/** Map a thrown gateway error into a coarse class. */
    91|export function classifyProviderFailure(error: unknown): IVXProviderFailureClass {
    92|  if (!error) return 'unknown';
    93|  const name = error instanceof Error ? error.name : '';
    94|  const message = error instanceof Error ? error.message.toLowerCase() : String(error).toLowerCase();
    95|  const statusMatch = message.match(/status=(\d{3})/);
    96|  const status = statusMatch ? Number.parseInt(statusMatch[1], 10) : null;
    97|
    98|  if (name === 'IVXAIGatewayTimeoutError' || message.includes('timed out') || message.includes('etimedout')) {
    99|    return 'timeout';
   100|  }
   101|  if (status === 401 || status === 403 || message.includes('unauthor') || message.includes('forbidden')) {
   102|    return 'auth';
   103|  }
   104|  if (status === 429 || message.includes('rate-limit') || message.includes('rate limit')) {
   105|    return 'rate_limit';
   106|  }
   107|  if (message.includes('insufficient_quota') || message.includes('quota')) {
   108|    return 'quota';
   109|  }
   110|  if (status && status >= 500) {
   111|    return 'server_error';
   112|  }
   113|  if (status === 400 || status === 422) {
   114|    return 'bad_request';
   115|  }
   116|  if (message.includes('econnreset') || message.includes('fetch failed') || message.includes('network')) {
   117|    return 'network';
   118|  }
   119|  return 'unknown';
   120|}
