   128|export function isFailureRetryable(cls: IVXProviderFailureClass): boolean {
   129|  return cls === 'timeout'
   130|    || cls === 'rate_limit'
   131|    || cls === 'quota'
   132|    || cls === 'server_error'
   133|    || cls === 'network'
