     5| * /api/public/chat/stream. Emits structured events so the UI can:
     6| *   - show a minimal typing indicator before first token
     7| *   - append deltas progressively to one assistant message
     8| *   - persist the final response
     9| *   - stop generation via AbortController
    10| *   - handle stream errors with retry
    11| *
    12| * Does NOT use setTimeout, fake typing, or post-hoc text splitting.
    13| * All deltas originate from the live AI gateway response.
    14| */
    15|import { getDirectApiBaseUrl } from '@/lib/api-base';
    16|import type { PublicChatHistoryItem } from './public-chat';
    17|
    18|// ── Stream event types ─────────────────────────────────────────────────────
    19|
    20|export type ChatStreamEvent =
    21|  | { type: 'response.started'; requestId: string; sessionId: string; timestamp: string }
    22|  | { type: 'response.delta'; delta: string; requestId: string }
    23|  | { type: 'response.completed'; text: string; model: string; source: string; endpoint?: string | null; requestId: string; sessionId: string; error?: string }
    24|  | { type: 'response.error'; error: string; requestId: string; sessionId: string };
    25|
    26|export type StreamCallbacks = {
    27|  onEvent: (event: ChatStreamEvent) => void;
    28|  onError: (error: string) => void;
    29|  onComplete: (finalText: string, model: string, source: string) => void;
    30|};
    31|
    32|export type StreamPublicChatInput = {
    33|  message: string;
    34|  history: PublicChatHistoryItem[];
    35|  sessionId: string;
    36|  requestId: string;
    37|  clientId?: string;
    38|  signal?: AbortSignal | null;
    39|};
    40|
    41|// ── Helpers ────────────────────────────────────────────────────────────────
    42|
    43|function buildStreamHeaders(clientId?: string): Record<string, string> {
    44|  const headers: Record<string, string> = {
    45|    'Content-Type': 'application/json',
    46|    'Accept': 'text/event-stream',
    47|  };
    48|  const trimmed = typeof clientId === 'string' ? clientId.trim() : '';
    49|  if (trimmed) {
    50|    headers['x-ivx-client-id'] = trimmed;
    51|  }
    52|  return headers;
    53|}
    54|
    55|function getStreamBaseUrl(): string {
    56|  return getDirectApiBaseUrl();
    57|}
    58|
    59|/**
    60| * Parse an SSE chunk into individual `data:` lines.
    61| * Each line is a JSON-encoded event.
    62| */
    63|function parseSSEChunk(chunk: string): string[] {
    64|  return chunk
    65|    .split('\n')
    66|    .filter((line) => line.startsWith('data: '))
    67|    .map((line) => line.slice(6).trim())
    68|    .filter((line) => line.length > 0);
    69|}
    70|
    71|// ── Main streaming function ────────────────────────────────────────────────
    72|
    73|/**
    74| * Stream a public chat message via SSE.
    75| *
    76| * Returns a promise that resolves when the stream completes (response.completed
    77| * or response.error). The caller can abort early via the AbortSignal — already
    78| * received text is preserved in the deltas emitted so far.
    79| */
    80|export async function streamPublicChatMessage(
    81|  input: StreamPublicChatInput,
    82|  callbacks: StreamCallbacks,
    83|): Promise<void> {
    84|  const baseUrl = getStreamBaseUrl();
    85|  const url = `${baseUrl}/public/chat/stream`;
    86|  const controller = new AbortController();
    87|
    88|  // Link external signal to our controller
    89|  if (input.signal) {
    90|    if (input.signal.aborted) {
    91|      controller.abort();
    92|    } else {
    93|      input.signal.addEventListener('abort', () => controller.abort(), { once: true });
    94|    }
    95|  }
    96|
    97|  let response: Response;
    98|  try {
    99|    response = await fetch(url, {
   100|      method: 'POST',
   101|      headers: buildStreamHeaders(input.clientId),
   102|      body: JSON.stringify({
   103|        requestId: input.requestId,
   104|        sessionId: input.sessionId,
   105|        message: input.message,
   106|        history: input.history,
   107|      }),
   108|      signal: controller.signal,
   109|    });
   110|  } catch (fetchError) {
   111|    if (controller.signal.aborted) {
   112|      // User stopped generation — not an error, just resolve
   113|      return;
   114|    }
   115|    const msg = fetchError instanceof Error ? fetchError.message : 'Network request failed.';
   116|    callbacks.onError(msg);
   117|    return;
   118|  }
   119|
   120|  if (!response.ok) {
   121|    let errMsg = `Request failed with HTTP ${response.status}.`;
   122|    try {
   123|      const text = await response.text();
   124|      const parsed = JSON.parse(text) as { error?: string };
   125|      if (parsed.error) errMsg = parsed.error;
   126|    } catch {
   127|      // use default error message
   128|    }
   129|    callbacks.onError(errMsg);
   130|    return;
   131|  }
   132|
   133|  const body = response.body;
   134|  if (!body) {
   135|    callbacks.onError('No response body received from streaming endpoint.');
   136|    return;
   137|  }
   138|
   139|  const reader = body.getReader();
   140|  const decoder = new TextDecoder();
   141|  let buffer = '';
   142|  let finalText = '';
   143|  let finalModel = 'unknown';
   144|  let finalSource = 'chatgpt';
   145|  let completed = false;
   146|
   147|  try {
   148|    while (true) {
   149|      const { done, value } = await reader.read();
   150|      if (done) break;
   151|
   152|      buffer += decoder.decode(value, { stream: true });
   153|
   154|      // Process complete SSE events (separated by \n\n)
   155|      const events = buffer.split('\n\n');
   156|      buffer = events.pop() ?? '';
   157|
   158|      for (const eventChunk of events) {
   159|        const lines = parseSSEChunk(eventChunk);
   160|        for (const line of lines) {
   161|          try {
   162|            const payload = JSON.parse(line) as ChatStreamEvent;
   163|            callbacks.onEvent(payload);
   164|
   165|            if (payload.type === 'response.completed') {
   166|              finalText = payload.text;
   167|              finalModel = payload.model;
   168|              finalSource = payload.source;
   169|              completed = true;
   170|            } else if (payload.type === 'response.error') {
   171|              callbacks.onError(payload.error);
   172|              completed = true;
   173|            }
   174|          } catch {
   175|            // Skip malformed JSON line
   176|          }
   177|        }
   178|      }
   179|    }
   180|
   181|    // Process any remaining buffer
   182|    if (buffer.length > 0) {
   183|      const lines = parseSSEChunk(buffer);
   184|      for (const line of lines) {
   185|        try {
   186|          const payload = JSON.parse(line) as ChatStreamEvent;
   187|          callbacks.onEvent(payload);
   188|          if (payload.type === 'response.completed') {
   189|            finalText = payload.text;
   190|            finalModel = payload.model;
   191|            finalSource = payload.source;
   192|            completed = true;
   193|          } else if (payload.type === 'response.error') {
   194|            callbacks.onError(payload.error);
   195|            completed = true;
   196|          }
   197|        } catch {
   198|          // Skip
   199|        }
   200|      }
   201|    }
   202|  } catch (readError) {
   203|    if (controller.signal.aborted) {
   204|      // User stopped — resolve with whatever we have
   205|      if (finalText.length > 0 || !completed) {
   206|        callbacks.onComplete(finalText, finalModel, finalSource);
   207|      }
   208|      return;
   209|    }
   210|    const msg = readError instanceof Error ? readError.message : 'Stream read failed.';
   211|    callbacks.onError(msg);
   212|    return;
   213|  } finally {
   214|    try {
   215|      reader.releaseLock();
   216|    } catch {
   217|      // already released
   218|    }
   219|  }
   220|
   221|  if (completed) {
   222|    callbacks.onComplete(finalText, finalModel, finalSource);
   223|  } else if (!controller.signal.aborted) {
   224|    // Stream ended without completion event
   225|    if (finalText.length > 0) {
   226|      callbacks.onComplete(finalText, finalModel, finalSource);
   227|    } else {
   228|      callbacks.onError('Stream ended unexpectedly without a response.');
   229|    }
   230|  }
